"""Independent computational verification for Conjecture 00000001288.

Conjecture 00000001288:
  "The SG function of the Turning Turtles game is generated by a homomorphism
   of the polynomial ring over Z_2 (the algebraization of Turning Turtles)."

This standalone Python 3 script (standard library only) independently verifies:
  1. Exact Sprague-Grundy values via game-tree mex vs. closed-form XOR formulas
     for both 0-indexed and 1-indexed Turning Turtles across all 4096 states on 12 coins.
  2. Surjective F_2-linear (additive group) homomorphism property G(f + g) = G(f) ^ G(g).
  3. Conway's recursive mex nim-multiplication vs. Fermat 2-power subfield arithmetic
     on F_2 = [0, 2), F_4 = [0, 4), and F_16 = [0, 16).
  4. Exact coincidence of 0-indexed Turning Turtles (sg0) with the unital nimber ring
     homomorphism ev_2 : Z_2[x] -> (N, xor, nim_mul) (x |-> 2) on ALL 8 polynomials of
     degree <= 2, and first breakdown at x^3 (sg0(x^3) = 4 != 1 = ev_2(x^3)).
  5. Universal Ring/Rng kernel-ideal counterexamples showing ker(sg0) and ker(sg1)
     are NOT ideals of Z_2[x] (nor of x * Z_2[x]), ruling out ALL codomain rings.
  6. Zero-Conductor verification across all 511 nonzero polynomials of degree <= 8,
     confirming that no nonzero ideal of Z_2[x] lies inside ker(sg0) or ker(sg1).
"""

from __future__ import annotations
from functools import lru_cache
import sys


def mex(values: set[int]) -> int:
    """Minimum excludant of a finite set of natural numbers."""
    m = 0
    while m in values:
        m += 1
    return m


def poly_add(p: int, q: int) -> int:
    """Addition in Z_2[x] (polynomials encoded by binary support bitmask)."""
    return p ^ q


def poly_mul(p: int, q: int) -> int:
    """Carryless multiplication in Z_2[x]."""
    acc = 0
    k = 0
    while (q >> k) > 0:
        if (q >> k) & 1:
            acc ^= p << k
        k += 1
    return acc


def poly_str(p: int) -> str:
    """Human-readable polynomial formatting in Z_2[x]."""
    if p == 0:
        return "0"
    terms = []
    k = 0
    while (1 << k) <= p:
        if (p >> k) & 1:
            if k == 0:
                terms.append("1")
            elif k == 1:
                terms.append("x")
            else:
                terms.append(f"x^{k}")
        k += 1
    return " + ".join(terms)


@lru_cache(maxsize=None)
def sg0_mex(mask: int) -> int:
    """True recursive mex Sprague-Grundy value of 0-indexed Turning Turtles."""
    options: set[int] = set()
    n = 0
    while (1 << n) <= mask:
        if (mask >> n) & 1:
            options.add(sg0_mex(mask ^ (1 << n)))
            for i in range(n):
                options.add(sg0_mex(mask ^ (1 << n) ^ (1 << i)))
        n += 1
    return mex(options)


@lru_cache(maxsize=None)
def sg1_mex(mask: int) -> int:
    """True recursive mex Sprague-Grundy value of 1-indexed Turning Turtles."""
    options: set[int] = set()
    n = 1
    while (1 << n) <= mask:
        if (mask >> n) & 1:
            options.add(sg1_mex(mask ^ (1 << n)))
            for i in range(1, n):
                options.add(sg1_mex(mask ^ (1 << n) ^ (1 << i)))
        n += 1
    return mex(options)


def sg0_xor_formula(mask: int) -> int:
    """Closed-form XOR formula for 0-indexed Turning Turtles: XOR_{k in S} (k + 1)."""
    ans = 0
    k = 0
    while (1 << k) <= mask:
        if (mask >> k) & 1:
            ans ^= k + 1
        k += 1
    return ans


def sg1_xor_formula(mask: int) -> int:
    """Closed-form XOR formula for 1-indexed Turning Turtles: XOR_{k >= 1, k in S} k."""
    ans = 0
    k = 1
    while (1 << k) <= mask:
        if (mask >> k) & 1:
            ans ^= k
        k += 1
    return ans


@lru_cache(maxsize=None)
def nim_mul_mex(a: int, b: int) -> int:
    """Conway's nim-multiplication defined directly by recursive mex."""
    seen: set[int] = set()
    for a1 in range(a):
        for b1 in range(b):
            seen.add(nim_mul_mex(a1, b) ^ nim_mul_mex(a, b1) ^ nim_mul_mex(a1, b1))
    return mex(seen)


def nim_pow(a: int, exp: int) -> int:
    """Iterated nim-power a^{\\otimes exp} in (N, xor, nim_mul)."""
    acc = 1
    for _ in range(exp):
        acc = nim_mul_mex(acc, a)
    return acc


def ev_nimber(alpha: int, poly_mask: int) -> int:
    """Unital ring homomorphism ev_alpha : Z_2[x] -> (N, xor, nim_mul), x |-> alpha."""
    ans = 0
    k = 0
    while (1 << k) <= poly_mask:
        if (poly_mask >> k) & 1:
            ans ^= nim_pow(alpha, k)
        k += 1
    return ans


def check_1_exact_sg_formulas() -> None:
    print("[1/6] Checking exact game-tree mex vs. XOR formulas on 4096 board states...")
    for mask in range(1 << 12):
        g0 = sg0_mex(mask)
        f0 = sg0_xor_formula(mask)
        if g0 != f0:
            raise AssertionError(f"sg0 mismatch at {mask}: mex={g0}, formula={f0}")
        g1 = sg1_mex(mask)
        f1 = sg1_xor_formula(mask)
        if g1 != f1:
            raise AssertionError(f"sg1 mismatch at {mask}: mex={g1}, formula={f1}")
    print("      PASS: sg0 and sg1 match closed-form XOR formulas on all 4096 positions.")


def check_2_f2_linearity_and_surjectivity() -> None:
    print("[2/6] Checking F_2-linearity G(p + q) = G(p) ^ G(q) and surjectivity...")
    for p in range(1 << 7):
        for q in range(1 << 7):
            if sg0_mex(poly_add(p, q)) != (sg0_mex(p) ^ sg0_mex(q)):
                raise AssertionError(f"sg0 linearity failed at p={p}, q={q}")
            if sg1_mex(poly_add(p, q)) != (sg1_mex(p) ^ sg1_mex(q)):
                raise AssertionError(f"sg1 linearity failed at p={p}, q={q}")
    for target in range(1, 65):
        mon0 = 1 << (target - 1)
        mon1 = 1 << target
        if sg0_xor_formula(mon0) != target:
            raise AssertionError(f"sg0 surjectivity witness failed at {target}")
        if sg1_xor_formula(mon1) != target or (mon1 & 1) != 0:
            raise AssertionError(f"sg1 surjectivity witness failed at {target}")
    print("      PASS: Both sg0 and sg1 are surjective F_2-linear maps (Z_2[x], +) -> (N, xor).")


def check_3_conway_fermat_subfields() -> None:
    print("[3/6] Checking Conway nim-multiplication field laws and Fermat subfields...")
    for bound in (2, 4, 16):
        for a in range(bound):
            for b in range(bound):
                if (a ^ b) >= bound:
                    raise AssertionError(f"XOR closure failed on [0, {bound})")
                prod = nim_mul_mex(a, b)
                if prod >= bound:
                    raise AssertionError(f"Nim-mul closure failed at {a} (*) {b} = {prod} >= {bound}")
                if prod != nim_mul_mex(b, a):
                    raise AssertionError(f"Nim-mul commutativity failed at {a}, {b}")
            if a != 0:
                invs = [b for b in range(bound) if nim_mul_mex(a, b) == 1]
                if len(invs) != 1:
                    raise AssertionError(f"Unique inverse failed for {a} in [0, {bound})")
    for a in range(8):
        for b in range(8):
            for c in range(8):
                if nim_mul_mex(nim_mul_mex(a, b), c) != nim_mul_mex(a, nim_mul_mex(b, c)):
                    raise AssertionError(f"Associativity failed at {a},{b},{c}")
                if nim_mul_mex(a, b ^ c) != (nim_mul_mex(a, b) ^ nim_mul_mex(a, c)):
                    raise AssertionError(f"Distributivity failed at {a},{b},{c}")
    print("      PASS: [0, 2), [0, 4), [0, 16) are closed Fermat subfields under (xor, nim_mul).")


def check_4_small_board_coincidence_and_nimber_refutation() -> None:
    print("[4/6] Checking degree<=2 coincidence with ev_2 and breakdown at x^3...")
    for p in range(1 << 5):
        for q in range(1 << 5):
            lhs = ev_nimber(2, poly_mul(p, q))
            rhs = nim_mul_mex(ev_nimber(2, p), ev_nimber(2, q))
            if lhs != rhs:
                raise AssertionError(f"ev_2 ring hom failed at {p}, {q}")

    for p in range(1 << 3):
        if sg0_mex(p) != ev_nimber(2, p):
            raise AssertionError(f"Expected sg0 == ev_2 on deg<=2 at {poly_str(p)}")

    x3 = 1 << 3
    if not (sg0_mex(x3) == 4 and ev_nimber(2, x3) == 1):
        raise AssertionError("Unexpected values at x^3")

    for alpha in range(16):
        image = {ev_nimber(alpha, p) for p in range(1 << 8)}
        if max(image) >= 16:
            raise AssertionError(f"ev_{alpha} escaped Fermat subfield [0, 16)")
    print(
        f"      PASS: sg0(p) == ev_2(p) for all 8 polynomials of degree <= 2, "
        f"breaking at x^3 (sg0(x^3) = {sg0_mex(x3)} != {ev_nimber(2, x3)} = ev_2(x^3))."
    )


def check_5_universal_kernel_non_ideal() -> None:
    print("[5/6] Checking universal ring/rng kernel-ideal counterexamples...")
    x = 0b10
    f0 = 0b111  # 1 + x + x^2
    xf0 = poly_mul(x, f0)  # x + x^2 + x^3
    if not (sg0_mex(f0) == 0 and sg0_mex(xf0) == 5):
        raise AssertionError("0-indexed kernel counterexample failed")

    f1 = 0b1110  # x + x^2 + x^3 in x * Z_2[x]
    xf1 = poly_mul(x, f1)  # x^2 + x^3 + x^4 in x * Z_2[x]
    if not ((f1 & 1) == 0 and (x & 1) == 0 and sg1_mex(f1) == 0 and sg1_mex(xf1) == 5):
        raise AssertionError("1-indexed kernel counterexample failed")

    print(
        f"      PASS: sg0({poly_str(f0)}) = 0 but sg0(x*({poly_str(f0)})) = {sg0_mex(xf0)} != 0;\n"
        f"            sg1({poly_str(f1)}) = 0 but sg1(x*({poly_str(f1)})) = {sg1_mex(xf1)} != 0."
    )


def check_6_zero_conductor() -> None:
    print("[6/6] Checking Zero-Conductor theorem on all 511 nonzero polynomials of degree <= 8...")
    for m in range(1, 1 << 9):
        d = m.bit_length() - 1
        r = d + 2
        k0 = (1 << r) - 1 - d
        k1 = (1 << r) - d
        p0 = poly_mul(1 << k0, m)
        p1 = poly_mul(1 << k1, m)
        g0 = sg0_xor_formula(p0)
        g1 = sg1_xor_formula(p1)
        if g0 == 0 or ((g0 >> r) & 1) != 1:
            raise AssertionError(f"sg0 zero-conductor failed for m={poly_str(m)}")
        if k1 < 1 or g1 == 0 or ((g1 >> r) & 1) != 1:
            raise AssertionError(f"sg1 zero-conductor failed for m={poly_str(m)}")
    print("      PASS: Every nonzero m (deg <= 8) admits k with sg0(x^k m) != 0 and sg1(x^k m) != 0.")


def main() -> int:
    print("=" * 72)
    print("Verification Suite for Conjecture 00000001288 (Turning Turtles & Z_2[x])")
    print("=" * 72)
    check_1_exact_sg_formulas()
    check_2_f2_linearity_and_surjectivity()
    check_3_conway_fermat_subfields()
    check_4_small_board_coincidence_and_nimber_refutation()
    check_5_universal_kernel_non_ideal()
    check_6_zero_conductor()
    print("=" * 72)
    print("ALL VERIFICATION CHECKS PASSED (Conjecture 00000001288: DISPROVED).")
    print("=" * 72)
    return 0


if __name__ == "__main__":
    sys.exit(main())
